function DashboardPage({ user }: { user?: User }) {
  const dashboard = useGetDashboard({ query: { queryKey: getGetDashboardQueryKey() } }); const [, setLocation] = useLocation();
  const counts = dashboard.data?.counts ?? {}; if (dashboard.isLoading) return <><SectionTitle eyebrow="Overview" title="Your coordination desk"/><SkeletonList rows={5}/></>; if (dashboard.isError) return <ErrorState retry={() => dashboard.refetch()}/>;
  return <><SectionTitle eyebrow="Overview" title={`Good morning, ${user?.name?.split(' ')[0] ?? 'team'}.`} description="A calm view of what is available, what is needed, and what needs your attention." action={<Button onClick={() => setLocation('/resources/new')} data-testid="button-dashboard-add"><Plus size={16}/> Add resource</Button>}/><div className="grid gap-4 sm:grid-cols-2 xl:grid-cols-4"><StatCard label="Available resources" value={counts.availableResources ?? counts.resources ?? 0} hint="Ready to be matched" icon={Package}/><StatCard label="Open requests" value={counts.openRequests ?? 0} hint="Needs a response" icon={ClipboardList} accent="coral"/><StatCard label="Active transfers" value={counts.activeTransactions ?? counts.transactions ?? 0} hint="In motion now" icon={Truck} accent="gold"/><StatCard label="Unread updates" value={dashboard.data?.unreadNotifications ?? 0} hint="Since your last visit" icon={Bell} accent="blue"/></div><div className="mt-6 grid gap-6 xl:grid-cols-[1.35fr_.65fr]"><div className="rounded-xl border border-card-border bg-card p-5"><div className="flex items-center justify-between"><div><h2 className="font-bold">Recently available</h2><p className="mt-1 text-xs text-muted-foreground">New surplus entering the network</p></div><Link href="/resources" className="text-xs font-bold text-primary hover:underline" data-testid="link-dashboard-resources">View all <ArrowRight className="ml-1 inline" size={13}/></Link></div><div className="mt-5 space-y-2">{dashboard.data?.recentResources?.slice(0, 5).map((resource) => <ResourceRow resource={resource} key={resource.id}/>) ?? <EmptyState title="No resources yet" description="When a donor lists surplus, it will appear here."/>}</div></div><div className="rounded-xl border border-card-border bg-card p-5"><div className="flex items-center justify-between"><div><h2 className="font-bold">Needs your response</h2><p className="mt-1 text-xs text-muted-foreground">Requests waiting on a decision</p></div><Link href="/requests" className="text-xs font-bold text-primary hover:underline" data-testid="link-dashboard-requests">Open queue <ArrowRight className="ml-1 inline" size={13}/></Link></div><div className="mt-5 space-y-3">{dashboard.data?.recentRequests?.slice(0, 4).map((request) => <RequestMini request={request} key={request.id}/>) ?? <EmptyState icon={ClipboardList} title="Queue is clear" description="No incoming requests need a response."/>}</div></div></div><div className="mt-6 rounded-xl border border-primary/20 bg-primary px-5 py-4 text-primary-foreground sm:flex sm:items-center sm:justify-between"><div><div className="flex items-center gap-2 font-semibold"><Sparkles size={17}/> Transparent matching is ready</div><p className="mt-1 text-sm text-primary-foreground/70">See exactly why available resources and open requests line up.</p></div><Link href="/recommendations" className="mt-3 inline-flex items-center gap-2 text-sm font-bold underline underline-offset-4 sm:mt-0" data-testid="link-dashboard-recommendations">Review matches <ArrowRight size={15}/></Link></div></>;
}

export default DashboardPage;
